public static class Ui {
 static Palette palette=Palette.Create(Preferences.Current);
 public static Palette Colors {get{return palette;}}
 public static Color Paper {get{return palette.Paper;}} public static Color Surface {get{return palette.Surface;}} public static Color Input {get{return palette.Input;}} public static Color Ink {get{return palette.Ink;}} public static Color Muted {get{return palette.Muted;}} public static Color Line {get{return palette.Line;}} public static Color Accent {get{return palette.Accent;}} public static Color Selection {get{return palette.Selection;}} public static Color Hover {get{return palette.Hover;}} public static Color Disabled {get{return palette.Disabled;}} public static Color OnAccent {get{return palette.OnAccent;}}
 public static Color SelectionInk {get{double a=Palette.Luminance(Accent),b=Palette.Luminance(Selection);return (Math.Max(a,b)+.05)/(Math.Min(a,b)+.05)>=3?Accent:Ink;}}
 public static void Configure(AppPreferences settings){palette=Palette.Create(settings);}
 [DllImport("dwmapi.dll")] static extern int DwmSetWindowAttribute(IntPtr window,int attribute,ref int value,int size);
 public static void TitleBar(Form form){if(!form.IsHandleCreated)return;try{int dark=palette.Dark?1:0;DwmSetWindowAttribute(form.Handle,20,ref dark,4);}catch{}}
 public static void Recolor(Control root,Palette old){
  Func<Color,Color> map=delegate(Color c){if(c.ToArgb()==old.Paper.ToArgb())return Paper;if(c.ToArgb()==old.Surface.ToArgb())return Surface;if(c.ToArgb()==old.Input.ToArgb())return Input;if(c.ToArgb()==old.Ink.ToArgb())return Ink;if(c.ToArgb()==old.Muted.ToArgb())return Muted;if(c.ToArgb()==old.Accent.ToArgb())return Accent;return c;};
  if(!Object.Equals(root.Tag,"accent-swatch")){root.BackColor=map(root.BackColor);root.ForeColor=map(root.ForeColor);}var link=root as LinkLabel;if(link!=null)link.LinkColor=SelectionInk;
  if(root.ContextMenuStrip!=null){root.ContextMenuStrip.Renderer=new ToolStripProfessionalRenderer(new UiMenuColors());root.ContextMenuStrip.BackColor=Paper;root.ContextMenuStrip.ForeColor=Ink;foreach(ToolStripItem item in root.ContextMenuStrip.Items){item.BackColor=Paper;item.ForeColor=Ink;}}
  foreach(Control c in root.Controls)Recolor(c,old);var form=root as Form;if(form!=null)TitleBar(form);root.Invalidate();
 }
 public static GraphicsPath Round(RectangleF r,float radius){var p=new GraphicsPath();float d=radius*2;p.AddArc(r.Left,r.Top,d,d,180,90);p.AddArc(r.Right-d,r.Top,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.Left,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
 public static void FitToScreen(Form form){var area=Screen.FromControl(form).WorkingArea;var room=new Size(Math.Max(640,area.Width-24),Math.Max(500,area.Height-24));form.MinimumSize=new Size(Math.Min(form.MinimumSize.Width,room.Width),Math.Min(form.MinimumSize.Height,room.Height));form.Size=new Size(Math.Min(form.Width,room.Width),Math.Min(form.Height,room.Height));form.Location=new Point(area.Left+(area.Width-form.Width)/2,area.Top+(area.Height-form.Height)/2);TitleBar(form);}
 public static void Theme(Control root){
  root.Font=new Font("Segoe UI",10);if(root is Form){var form=(Form)root;form.Shown+=delegate{FitToScreen(form);};}if(root is Form||root is Panel||root is TableLayoutPanel||root is FlowLayoutPanel){root.BackColor=Paper;root.ForeColor=Ink;}
  if(root is Label){root.ForeColor=root.ForeColor==Color.FromArgb(92,245,156)?Accent:root.ForeColor==Color.FromArgb(151,166,184)?Muted:Ink;}
  if(root is TextBox){root.BackColor=Input;root.ForeColor=Ink;((TextBox)root).BorderStyle=BorderStyle.FixedSingle;}
  if(root is NumericUpDown){root.BackColor=Input;root.ForeColor=Ink;((NumericUpDown)root).BorderStyle=BorderStyle.None;}
  if(root is ComboBox){root.BackColor=Input;root.ForeColor=Ink;((ComboBox)root).FlatStyle=FlatStyle.Flat;}
  if(root is CheckBox||root is TrackBar){root.BackColor=Paper;root.ForeColor=Ink;}
  if(root is Button&&!(root is ModernButton)&&!Object.Equals(root.Tag,"accent-swatch")){var b=(Button)root;b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Line;b.BackColor=Surface;b.ForeColor=Ink;}
  foreach(Control c in root.Controls)Theme(c);L.Localize(root);
 }
