public class ModernNumber : NumericUpDown {
 public ModernNumber(){BorderStyle=BorderStyle.None;BackColor=Ui.Input;ForeColor=Ui.Ink;Font=new Font("Segoe UI",10);}
 protected override void OnLayout(LayoutEventArgs e){base.OnLayout(e);foreach(Control c in Controls){c.BackColor=Ui.Input;c.ForeColor=Ui.Ink;if(c is TextBoxBase)c.Bounds=new Rectangle(0,0,Width,Height);else{c.Visible=false;c.Width=0;}}}
 public void RefreshFormatting(){UpdateEditText();}
}
public class ModernCombo : ComboBox {
 public ModernCombo(){FlatStyle=FlatStyle.Flat;BackColor=Ui.Input;ForeColor=Ui.Ink;DrawMode=DrawMode.OwnerDrawFixed;ItemHeight=26;DropDownStyle=ComboBoxStyle.DropDownList;}
 protected override void OnDrawItem(DrawItemEventArgs e){if(e.Index<0)return;bool selected=(e.State&DrawItemState.Selected)!=0;using(var bg=new SolidBrush(selected?Ui.Selection:Ui.Input))e.Graphics.FillRectangle(bg,e.Bounds);TextRenderer.DrawText(e.Graphics,GetItemText(Items[e.Index]),Font,new Rectangle(e.Bounds.X+8,e.Bounds.Y,e.Bounds.Width-12,e.Bounds.Height),selected?Ui.SelectionInk:Ui.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}
}
public class ModernButton : Button {
 public bool Primary,Selected,Quiet;public string Glyph="";bool hovered;
 public ModernButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;BackColor=Ui.Paper;ForeColor=Ui.Ink;Font=new Font("Segoe UI",9.5f);Height=34;Cursor=Cursors.Hand;Margin=new Padding(3,0,3,0);}
 public override Size GetPreferredSize(Size proposedSize){if(!AutoSize)return base.GetPreferredSize(proposedSize);var measured=TextRenderer.MeasureText(Text,Font);return new Size(measured.Width+(Glyph.Length>0?45:24),Math.Max(34,Height));}
 protected override void OnMouseEnter(EventArgs e){hovered=true;Invalidate();base.OnMouseEnter(e);}
 protected override void OnMouseLeave(EventArgs e){hovered=false;Invalidate();base.OnMouseLeave(e);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Parent==null?Ui.Paper:Parent.BackColor);Color bg=Primary?Ui.Accent:Selected?Ui.Selection:hovered?Ui.Hover:Quiet?BackColor:Ui.Surface;Color fg=!Enabled?Ui.Disabled:Primary?Ui.OnAccent:Selected?Ui.SelectionInk:Ui.Ink;using(var shape=Ui.Round(new RectangleF(0,0,Width-1,Height-1),7))using(var b=new SolidBrush(bg))g.FillPath(b,shape);bool hasText=!String.IsNullOrEmpty(Text);int iconX=hasText?12:(Width-18)/2;if(Glyph.Length>0)DrawGlyph(g,Glyph,new Rectangle(iconX,(Height-18)/2,18,18),fg);if(hasText){var rect=new Rectangle(Glyph.Length>0?37:10,0,Width-(Glyph.Length>0?45:20),Height);TextRenderer.DrawText(g,Text,Font,rect,fg,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|(Glyph.Length==0?TextFormatFlags.HorizontalCenter:TextFormatFlags.Left));}if(Focused){using(var p=new Pen(Color.FromArgb(140,Ui.Accent),1))g.DrawRectangle(p,3,3,Width-8,Height-8);}}
 public static void DrawGlyph(Graphics g,string kind,Rectangle r,Color color){var save=g.Save();g.TranslateTransform(r.X,r.Y);g.ScaleTransform(r.Width/18f,r.Height/18f);using(var p=new Pen(color,1.5f)){p.StartCap=p.EndCap=LineCap.Round;p.LineJoin=LineJoin.Round;using(var b=new SolidBrush(color)){
  switch(kind){
   case "select":g.DrawPolygon(p,new[]{new PointF(4,2),new PointF(14,10),new PointF(9,11),new PointF(7,16)});break;
   case "line":g.DrawLine(p,3,15,15,3);g.FillEllipse(b,1.5f,13.5f,3,3);g.FillEllipse(b,13.5f,1.5f,3,3);break;
   case "circle":g.DrawEllipse(p,3,3,12,12);break;
   case "rect":g.DrawRectangle(p,3,4,12,10);break;
   case "fill":g.FillRectangle(b,3,4,12,10);break;
   case "triangle":g.DrawPolygon(p,new[]{new PointF(9,2),new PointF(16,15),new PointF(2,15)});break;
   case "pen":g.DrawLines(p,new[]{new PointF(3,14),new PointF(3,10),new PointF(12,2),new PointF(16,6),new PointF(7,15),new PointF(3,15)});g.DrawLine(p,10,4,14,8);break;
   case "text":g.DrawLine(p,3,3,15,3);g.DrawLine(p,9,3,9,15);g.DrawLine(p,6,15,12,15);break;
   case "image":g.DrawRectangle(p,2,3,14,12);g.DrawLines(p,new[]{new PointF(3,13),new PointF(7,8),new PointF(10,11),new PointF(13,7),new PointF(16,12)});g.DrawEllipse(p,5,5,2,2);break;
   case "folder":g.DrawPolygon(p,new[]{new PointF(2,5),new PointF(7,5),new PointF(8,3),new PointF(15,3),new PointF(16,14),new PointF(2,14)});break;
   case "save":g.DrawRectangle(p,3,2,12,14);g.DrawRectangle(p,6,2,6,5);g.DrawRectangle(p,6,11,6,5);break;
   case "export":g.DrawLine(p,9,2,9,11);g.DrawLines(p,new[]{new PointF(5,6),new PointF(9,2),new PointF(13,6)});g.DrawLines(p,new[]{new PointF(3,10),new PointF(3,15),new PointF(15,15),new PointF(15,10)});break;
   case "import":g.DrawLine(p,9,2,9,11);g.DrawLines(p,new[]{new PointF(5,7),new PointF(9,11),new PointF(13,7)});g.DrawLines(p,new[]{new PointF(3,10),new PointF(3,15),new PointF(15,15),new PointF(15,10)});break;
   case "copy":g.DrawRectangle(p,6,6,9,10);g.DrawLines(p,new[]{new PointF(3,12),new PointF(3,2),new PointF(12,2)});break;
   case "delete":g.DrawLine(p,3,5,15,5);g.DrawLine(p,7,2,11,2);g.DrawLines(p,new[]{new PointF(5,5),new PointF(6,16),new PointF(12,16),new PointF(13,5)});break;
   case "undo":g.DrawArc(p,5,5,10,10,210,230);g.DrawLines(p,new[]{new PointF(3,2),new PointF(3,8),new PointF(9,8)});break;
   case "redo":g.DrawArc(p,3,5,10,10,100,230);g.DrawLines(p,new[]{new PointF(15,2),new PointF(15,8),new PointF(9,8)});break;
   case "plus":g.DrawLine(p,3,9,15,9);g.DrawLine(p,9,3,9,15);break;
   case "color":g.DrawEllipse(p,3,3,12,12);g.FillPie(b,3,3,12,12,45,180);break;
   case "settings":g.DrawEllipse(p,4,4,10,10);g.DrawEllipse(p,7,7,4,4);for(int i=0;i<8;i++){double angle=i*Math.PI/4;g.DrawLine(p,9+(float)Math.Cos(angle)*5,9+(float)Math.Sin(angle)*5,9+(float)Math.Cos(angle)*8,9+(float)Math.Sin(angle)*8);}break;
   case "scope":g.DrawEllipse(p,4,4,10,10);g.DrawLine(p,9,0,9,6);g.DrawLine(p,9,12,9,18);g.DrawLine(p,0,9,6,9);g.DrawLine(p,12,9,18,9);break;
  }
 }}g.Restore(save);}
}
