  templateList.Location=new Point(10,74);templateList.Size=new Size(211,400);templateList.Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;templateList.BorderStyle=BorderStyle.None;templateList.BackColor=Ui.Paper;templateList.ForeColor=Ui.Ink;templateList.DrawMode=DrawMode.OwnerDrawFixed;templateList.ItemHeight=40;templateList.DrawItem+=delegate(object s,DrawItemEventArgs e){if(e.Index<0)return;bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(selected?Ui.Selection:Ui.Paper))e.Graphics.FillRectangle(b,e.Bounds);TextRenderer.DrawText(e.Graphics,templateList.Items[e.Index].ToString(),templateList.Font,new Rectangle(e.Bounds.X+8,e.Bounds.Y,e.Bounds.Width-12,e.Bounds.Height),selected?Ui.SelectionInk:Ui.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);};templatePane.Controls.Add(templateList);
  var apply=ButtonFor(templatePane,L.T("Использовать шаблон"),"",198,delegate{if(templateList.SelectedIndex<0)return;templates.SelectedIndex=templateIndices[templateList.SelectedIndex];if(ConfirmLoss())SetDocument(ChosenTemplate(),"");});apply.Anchor=AnchorStyles.Bottom|AnchorStyles.Left;templatePane.Resize+=delegate{templateList.Height=Math.Max(50,templatePane.Height-136);apply.Location=new Point(16,templatePane.Height-48);};templateSearch.TextChanged+=delegate{FilterTemplates();};templateList.DoubleClick+=delegate{apply.PerformClick();};FilterTemplates();
 }
 void FilterTemplates(){templateList.Items.Clear();templateIndices.Clear();string query=templateSearch.Text.Trim();for(int i=0;i<templates.Items.Count;i++){string name=TemplateTitle(i);if(query.Length>0&&name.IndexOf(query,StringComparison.OrdinalIgnoreCase)<0&&templates.Items[i].ToString().IndexOf(query,StringComparison.OrdinalIgnoreCase)<0)continue;templateIndices.Add(i);templateList.Items.Add(name);}if(templateList.Items.Count>0)templateList.SelectedIndex=0;}
 string TemplateTitle(int index){if(index<3)return templates.Items[index].ToString();var item=gameTemplates[index-3];var names=new Dictionary<string,string>{{"short_range_sight",L.T("WT · Стандартный")},{"us_modern_sight_with_range",L.T("WT · США · с дальностью")},{"us_modern_sight_without_range",L.T("WT · США · без дальности")},{"ussr_modern_sight_with_range",L.T("WT · СССР · современный")},{"ussr_sosna_u_sight",L.T("WT · Сосна-У")},{"leclerc_v1","WT · Leclerc"},{"challenger2","WT · Challenger 2"},{"cn_ring",L.T("WT · Китай · кольцо")},{"cn_triangulation",L.T("WT · Китай · треугольник")}};return names.ContainsKey(item.Name)?names[item.Name]:"WT · "+item.Name.Replace('_',' ');}
 void ShowSidebar(bool library){templatePane.Visible=library;layerPane.Visible=!library;if(elementTab!=null){elementTab.Selected=!library;templateTab.Selected=library;elementTab.Invalidate();templateTab.Invalidate();}}
 void PaintLayer(object sender,DrawItemEventArgs e){if(e.Index<0||Doc==null||e.Index>=Doc.Parts.Count)return;var part=Doc.Parts[e.Index];bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(selected?Ui.Selection:Ui.Paper))using(var path=Ui.Round(new RectangleF(e.Bounds.X+2,e.Bounds.Y+2,e.Bounds.Width-5,e.Bounds.Height-4),7))e.Graphics.FillPath(b,path);string icon=part.Kind=="quad"?"fill":part.Kind=="image"?"image":part.Kind;ModernButton.DrawGlyph(e.Graphics,icon,new Rectangle(e.Bounds.X+12,e.Bounds.Y+10,17,17),selected?Ui.Accent:Ui.Muted);TextRenderer.DrawText(e.Graphics,L.T(part.Name)+(new[]{L.T("Линия"),L.T("Окружность"),L.T("Фигура"),L.T("Текст")}.Contains(part.Name)?" "+(e.Index+1).ToString("00"):""),layers.Font,new Rectangle(e.Bounds.X+39,e.Bounds.Y,e.Bounds.Width-47,e.Bounds.Height),part.Visible?Ui.Ink:Ui.Muted,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}
 void BuildInspector(){
  props.Controls.Add(Caption(L.T("СВОЙСТВА"),20,18));elementHeading.Text=L.T("Выберите элемент");elementHeading.Location=new Point(20,45);elementHeading.Size=new Size(242,28);elementHeading.Font=new Font("Segoe UI",13,FontStyle.Bold);props.Controls.Add(elementHeading);elementHint.Text=L.T("Параметры появятся после выбора\nэлемента на холсте или в списке.");elementHint.Location=new Point(20,88);elementHint.Size=new Size(240,50);elementHint.ForeColor=Ui.Muted;props.Controls.Add(elementHint);
  foreach(string key in new[]{"X","Y","X2","Y2","Size","Start","End"}){var label=Caption(key,24,0,110);label.Name=key=="Size"?"elementSizeLabel":"label"+key;fieldLabels[key]=label;props.Controls.Add(label);var n=new ModernNumber{Width=102,Minimum=-1000000,Maximum=1000000,DecimalPlaces=4,Increment=0.01M};numbers[key]=n;n.ValueChanged+=PropertyChanged;props.Controls.Add(n);}
  text.BorderStyle=BorderStyle.None;text.BackColor=Ui.Input;text.ForeColor=Ui.Ink;text.Width=228;text.TextChanged+=PropertyChanged;props.Controls.Add(text);fieldLabels["Text"]=Caption(L.T("Надпись"),24,0);props.Controls.Add(fieldLabels["Text"]);
  visible.Text=L.T("Показывать элемент");move.Text=L.T("Двигать с поправкой дальности");mils.Text=L.T("Координаты в тысячных");foreach(var cb in new[]{visible,move,mils}){cb.Size=new Size(242,27);cb.CheckedChanged+=PropertyChanged;props.Controls.Add(cb);}
  var width=new ModernNumber{Name="width",Width=228,Minimum=0.1M,Maximum=20,DecimalPlaces=1,Increment=0.1M,Value=1.5M};width.ValueChanged+=delegate{if(syncing)return;Remember();Doc.LineWidth=(double)width.Value;Changed();};props.Controls.Add(width);fieldLabels["Width"]=Caption(L.T("Толщина всей сетки"),24,0);props.Controls.Add(fieldLabels["Width"]);
  strokeWidth=new ModernNumber{Width=228,Minimum=0.1M,Maximum=100,DecimalPlaces=2,Increment=0.1M,Value=1};strokeWidth.ValueChanged+=delegate{if(syncing||L.Applying||Selected==null)return;Remember();Selected.StrokeWidth=(double)strokeWidth.Value;Changed();};props.Controls.Add(strokeWidth);fieldLabels["Stroke"]=Caption(L.T("Толщина элемента"),24,0);props.Controls.Add(fieldLabels["Stroke"]);
  textAlign=new ModernCombo{Width=228};textAlign.Items.AddRange(new object[]{L.T("По центру"),L.T("От точки вправо"),L.T("От точки влево")});textAlign.SelectedIndex=0;textAlign.SelectedIndexChanged+=delegate{if(syncing||L.Applying||Selected==null)return;Remember();Selected.Align=textAlign.SelectedIndex;Changed();};props.Controls.Add(textAlign);fieldLabels["Align"]=Caption(L.T("Выравнивание"),24,0);props.Controls.Add(fieldLabels["Align"]);
  textHighlight.Text=L.T("Подсветка текста в игре");textHighlight.Size=new Size(240,27);textHighlight.CheckedChanged+=delegate{if(syncing||L.Applying||Selected==null)return;Remember();Selected.Highlight=textHighlight.Checked;Changed();};props.Controls.Add(textHighlight);
  angularUnits=new ModernCombo{Width=228};angularUnits.Items.AddRange(new object[]{L.T("СССР · 1/6000"),"NATO · 1/6400",L.T("Радианная · 1/6283")});angularUnits.SelectedIndex=0;angularUnits.SelectedIndexChanged+=delegate{if(!syncing)SetNative("thousandth","t",Blk.Quote(new[]{"ussr","nato","real"}[angularUnits.SelectedIndex]));};props.Controls.Add(angularUnits);fieldLabels["Units"]=Caption(L.T("Система тысячных"),24,0);props.Controls.Add(fieldLabels["Units"]);
  centralVert.Text=L.T("Стандартная вертикаль");centralHorz.Text=L.T("Стандартная горизонталь");foreach(var cb in new[]{centralVert,centralHorz}){cb.Size=new Size(242,27);props.Controls.Add(cb);}centralVert.CheckedChanged+=delegate{SetNative("drawCentralLineVert","b",centralVert.Checked?"yes":"no");};centralHorz.CheckedChanged+=delegate{SetNative("drawCentralLineHorz","b",centralHorz.Checked?"yes":"no");};snapGrid.Text=L.T("Привязка к сетке");snapGrid.Size=new Size(240,27);props.Controls.Add(snapGrid);
  advancedButton=ButtonFor(props,L.T("Параметры WT  +"),"",240,delegate{advanced=!advanced;LayoutInspector();});advancedButton.Quiet=true;
 }
 void PlaceField(string key,string title,int x,int y,int width=228){var label=fieldLabels[key];var control=numbers.ContainsKey(key)?(Control)numbers[key]:key=="Text"?text:key=="Stroke"?strokeWidth:key=="Align"?textAlign:key=="Width"?props.Controls["width"]:angularUnits;label.Text=title;label.Location=new Point(x,y);label.Width=width;label.Visible=true;control.AccessibleName=title;control.Location=new Point(x,y+25);control.Width=width;control.Visible=true;}
 void LayoutInspector(){if(advancedButton==null||Doc==null)return;props.SuspendLayout();int scroll=props.AutoScrollPosition.Y;props.AutoScrollPosition=Point.Empty;foreach(var n in numbers.Values)n.Visible=false;foreach(var l in fieldLabels.Values)l.Visible=false;foreach(Control c in new Control[]{text,visible,move,mils,strokeWidth,textAlign,textHighlight,angularUnits,centralVert,centralHorz,props.Controls["width"],snapGrid})c.Visible=false;var p=Selected;elementHeading.Text=p==null?L.T("Выберите элемент"):p.Kind=="line"?L.T("Линия"):p.Kind=="circle"?L.T("Окружность"):p.Kind=="text"?L.T("Текст"):p.Kind=="image"?L.T("Рисунок"):L.T("Фигура");elementHint.Visible=p==null;int y=91;
  if(p!=null){PlaceField("X",L.T("Положение X"),24,y,102);PlaceField("Y",L.T("Положение Y"),152,y,102);y+=66;if(p.Kind=="line"||(p.Kind=="quad"&&String.IsNullOrEmpty(p.Original))){PlaceField("X2",L.T("Конец X"),24,y,102);PlaceField("Y2",L.T("Конец Y"),152,y,102);y+=66;}if(p.Kind=="circle"||p.Kind=="text"||p.Kind=="image"){PlaceField("Size",p.Kind=="image"?L.T("Ширина рисунка"):p.Kind=="circle"?L.T("Диаметр"):L.T("Размер текста"),24,y);y+=66;}if(p.Kind=="circle"){PlaceField("Start",L.T("Начало дуги, °"),24,y,102);PlaceField("End",L.T("Конец дуги, °"),152,y,102);y+=66;}if(p.Kind=="text"){PlaceField("Text",L.T("Надпись"),24,y);y+=66;PlaceField("Align",L.T("Выравнивание"),24,y);y+=70;}if(p.Kind=="line"||p.Kind=="circle"){PlaceField("Stroke",L.T("Толщина элемента"),24,y);y+=66;}visible.Location=new Point(20,y);visible.Visible=true;y+=35;}
  else y+=68;
  snapGrid.Location=new Point(20,y);snapGrid.Visible=true;y+=43;advancedButton.Location=new Point(18,y);advancedButton.Text=advanced?L.T("Параметры WT  −"):L.T("Параметры WT  +");y+=48;
  if(advanced){if(p!=null){move.Location=new Point(20,y);move.Visible=true;y+=32;mils.Location=new Point(20,y);mils.Visible=true;y+=35;if(p.Kind=="text"){textHighlight.Location=new Point(20,y);textHighlight.Visible=true;y+=35;}}PlaceField("Width",L.T("Толщина всей сетки"),24,y);y+=66;PlaceField("Units",L.T("Система тысячных"),24,y);y+=72;centralVert.Location=new Point(20,y);centralVert.Visible=true;y+=32;centralHorz.Location=new Point(20,y);centralHorz.Visible=true;y+=40;}
  props.AutoScrollMinSize=new Size(0,y+14);props.ResumeLayout();props.AutoScrollPosition=new Point(0,Math.Max(0,-scroll));props.Invalidate();
 }
 void PaintInputBorders(object sender,PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;foreach(Control c in props.Controls)if(c.Visible&&(c is NumericUpDown||c is TextBox)){var rect=new RectangleF(c.Left-6,c.Top-4,c.Width+12,c.Height+8);using(var path=Ui.Round(rect,6))using(var b=new SolidBrush(Ui.Input))e.Graphics.FillPath(b,path);}}
 void UpdateModernHeader(){if(Doc==null)return;projectHeading.Text=L.T(Doc.Title)+(dirty?L.T("  ·  Несохранённые изменения"):"");layerCount.Text=Doc.Parts.Count+L.T(" элементов");if(undoButton!=null){undoButton.Enabled=undo.Count>0;redoButton.Enabled=redo.Count>0;}layers.Invalidate();}
 void ModernShortcuts(object sender,KeyEventArgs e){if(e.Control||e.Alt||!(canvas.ContainsFocus||layers.ContainsFocus||ActiveControl is ModernButton))return;string keys="VLOR BGP".Replace(" ","");int index=keys.IndexOf((char)e.KeyCode);if(index>=0&&index<7){drawingTool.SelectedIndex=index;canvas.Focus();e.SuppressKeyPress=true;}if(e.KeyCode==Keys.T){AddPart("text");drawingTool.SelectedIndex=0;e.SuppressKeyPress=true;}}
}
